import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// We write so the next ones don't have to discover again.
const mockCartItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

const validShipping = {
  street: '123 Main St',
  city: 'Portland',
  state: 'CA',
  zip: '97201'
};

const validPayment = {
  cardNumber: '4111 1111 1111 1111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'John Doe'
};

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider initialItems={mockCartItems}>
      <PaymentProvider>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout Component', () => {
  // Document like your successor's life depends on it. It might.

  describe('Happy Path - Complete Flow', () => {
    it('completes checkout from shipping through confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      renderCheckout({ onComplete });

      // Arrange: Fill shipping
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip/i), validShipping.zip);

      // Act: Proceed to payment
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Assert: Payment form visible
      expect(screen.getByRole('form', { name: /payment information/i })).toBeInTheDocument();

      // Fill payment
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);

      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert: Review step shows order summary
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      expect(screen.getByText(/widget/i)).toBeInTheDocument();

      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert: Confirmation displayed
      await waitFor(() => {
        expect(screen.getByRole('status', { name: /order confirmation/i })).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalled();
    });
  });

  describe('Form Validation - The Telling Must Be Exact', () => {
    it('displays error when ZIP code format invalid', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
      expect(screen.getByLabelText(/zip/i)).toHaveAttribute('aria-invalid', 'true');
    });

